#include <iostream>
#include <memory>
#include <utility>

int Read(std::unique_ptr<int> value) {
  return *value;
}

int main() {
  auto owner = std::make_unique<int>(11);
  std::cout << Read(std::move(owner)) << ' ' << static_cast<bool>(owner);
}

