    std::cout << 'C';
  }
  std::cout << 'D';
}

#include <iostream>

int Encode(int a, int b, int c) {
  return 100 * a + 10 * b + c;
}

template <typename... Ts>
int Build(Ts... values) {
  return Encode((values + 1)...);
}

int main() {
  std::cout << Build(1, 3, 5);
}

#include <iostream>

template <typename... Checks>
bool Run(Checks... checks) {
  return (... && checks());
}

int main() {
  std::cout << Run([] { return true; },
                   [] { return false; },
                   [] { return true; });
}

#include <iostream>

template <typename... Ts>
int Remaining(int budget, Ts... costs) {
  return (budget - ... - costs);
}

int main() {
  std::cout << Remaining(50) << ' ' << Remaining(50, 4, 6);
}
